export function applyTimedEffect(entity,{id,kind="buff",stats={},durationMs,sourceId=null,now=Date.now(),stacking="refresh"}){if(!id||!Number.isFinite(durationMs)||durationMs<=0)throw new TypeError("Effect id and positive duration required");entity.effects||=[];const current=entity.effects.find(e=>e.id===id);if(current&&stacking==="ignore")return current;if(current&&stacking==="stack"){current.stacks=(current.stacks||1)+1;current.expiresAt=now+durationMs;return current;}const effect={id,kind,stats,sourceId,appliedAt:now,expiresAt:now+durationMs,stacks:1};entity.effects=entity.effects.filter(e=>e.id!==id);entity.effects.push(effect);return effect;}
export function expireEffects(entity,now=Date.now()){entity.effects=(entity.effects||[]).filter(e=>e.expiresAt>now);return entity.effects;}
export function aggregateEffectStats(entity,now=Date.now()){expireEffects(entity,now);return entity.effects.reduce((sum,e)=>{for(const [k,v] of Object.entries(e.stats))sum[k]=(sum[k]||0)+v*(e.stacks||1);return sum;},{});}
